INSERT INTO value_statuses VALUES ('observe', 'Publié', true, 'Valeur reprise telle quelle de la source.');
INSERT INTO value_statuses VALUES ('calcule', 'Calculé', true, 'Ratio ou somme de valeurs publiées, selon la formule du dictionnaire.');
INSERT INTO value_statuses VALUES ('zero_reel', 'Zéro réel', true, 'Zéro établi par la source, par exemple aucun établissement dans la liste officielle.');
INSERT INTO value_statuses VALUES ('estime', 'Estimé', true, 'Valeur absente de la source, remplacée par une estimation documentée (par exemple la valeur régionale).');
INSERT INTO value_statuses VALUES ('convention', 'Convention', true, 'Valeur fixée par une règle documentée, par exemple « sans objet » compté 0.');
INSERT INTO value_statuses VALUES ('manquant', 'Manquant', false, 'Valeur attendue mais absente de la source.');
INSERT INTO value_statuses VALUES ('non_publie', 'Non publié', false, 'Le producteur ne publie pas cette valeur à ce niveau géographique.');
INSERT INTO value_statuses VALUES ('confidentiel', 'Confidentiel', false, 'Valeur masquée par le producteur (secret statistique).');
